    27	/**
    28	 * fixes indentation by removing leading spaces and tabs from each line
    29	 */
    30	function fixIndent(str: string): string {
    31	  const trimmedStr = str
    32	    .replace(/^\n*/m, '') //  remove leading newline
    33	    .replace(/[ \t]*$/, ''); // remove trailing spaces and tabs
    34	  const indentMatch = /^[ \t]*/.exec(trimmedStr);
    35	  invariant(Array.isArray(indentMatch));
    36	  const indent = indentMatch[0]; // figure out indent
    37	  return trimmedStr.replace(RegExp('^' + indent, 'mg'), ''); // remove indent
    38	}
