    40	/**
    41	 * An ES6 string tag that fixes indentation. Also removes leading newlines
    42	 * and trailing spaces and tabs, but keeps trailing newlines.
    43	 *
    44	 * Example usage:
    45	 * const str = dedent`
    46	 *   {
    47	 *     test
    48	 *   }
    49	 * `;
    50	 * str === "{\n  test\n}\n";
    51	 */
    52	export default function dedent(
    53	  strings: string | Array<string>,
    54	  ...values: Array<string>
    55	): string {
    56	  // when used as an ordinary function, allow passing a singleton string
    57	  const strArray = typeof strings === 'string' ? [strings] : strings;
    58	  const numValues = values.length;
    59	
    60	  const str = strArray.reduce((prev, cur, index) => {
    61	    let next = prev + cur;
    62	    if (index < numValues) {
    63	      next += values[index]; // interpolation
    64	    }
    65	    return next;
    66	  }, '');
    67	
    68	  return fixIndent(str);
    69	}
