```js
  it('passes GraphQLError-ish through', () => {
    const e = new Error('I have a different prototype chain');
    const ish: any = e;
    ish.locations = [];
    ish.path = [];
    ish.nodes = [];
    ish.source = null;
    ish.positions = [];
    e.name = 'GraphQLError';

