'use strict';
const fs = require('fs');
const path = require('path');
const dir = process.argv[2];
const text = fs.readFileSync(path.join(dir, 'summary.md'), 'utf8');

function section(heading) {
  const start = text.indexOf(heading + '\n');
  if (start < 0) throw new Error('missing heading: ' + heading);
  const bodyStart = start + heading.length + 1;
  const next = text.slice(bodyStart).search(/^#{2,3} /m);
  return text.slice(bodyStart, next < 0 ? undefined : bodyStart + next).trim();
}

const anchors = [
  ['src/error/__tests__/GraphQLError-test.js', 57, 64],
  ['src/error/GraphQLError.js', 25, 25],
  ['src/jsutils/__tests__/inspect-test.js', 31, 32],
  ['src/error/__tests__/printError-test.js', 52, 84],
  ['src/error/__tests__/locatedError-test.js', 29, 41],
];

const headings = text.match(/^### \d+\. .*$/gm);
if (headings.length !== anchors.length) throw new Error('heading count');
const findings = headings.map((h, i) => {
  const quote = section(h);
  if (!text.includes(quote)) throw new Error('quote not verbatim');
  return {
    report_path: 'summary.md',
    title: h.replace(/^### /, ''),
    quote,
    file: anchors[i][0],
    line_start: anchors[i][1],
    line_end: anchors[i][2],
  };
});

const qHeading = '## Question for the author';
const qQuote = section(qHeading);
if (!text.includes(qQuote)) throw new Error('question not verbatim');
const questions = [
  {
    report_path: 'summary.md',
    title: qHeading.replace(/^## /, ''),
    quote: qQuote,
    file: 'src/error/GraphQLError.js',
    line_start: 25,
    line_end: 25,
  },
];

fs.writeFileSync(
  path.join(dir, 'finding-index.json'),
  JSON.stringify({ findings, questions }, null, 2) + '\n',
);
console.log(findings.map(f => f.title + ' [' + f.quote.length + ' chars]').join('\n'));
console.log('questions:', questions.length);
EOF
